import json
from collections import Counter

with open("/root/trace_distill_repair/pipeline_output/phase2_line_scores.json") as f:
    data = json.load(f)

# Top-level metadata
print(f"mode={data['mode']}, instances={data['num_instances']}, total_segs={data['total_segments']}")
print(f"scored={data['scored_segments']}, failed={data['failed_segments']}, elapsed={data['elapsed_seconds']:.0f}s")
print(f"excluded={data.get('excluded', [])}")

# Results structure
results = data["results"]
print(f"\nResults: {len(results)} instances")

# Inspect first entry structure
first_key = list(results.keys())[0]
first_val = results[first_key]
print(f"\nSample [{first_key}]: type={type(first_val).__name__}")
if isinstance(first_val, dict):
    print(f"  keys: {list(first_val.keys())[:10]}")
    for sk in list(first_val.keys())[:2]:
        sv = first_val[sk]
        print(f"  [{sk}]: type={type(sv).__name__}")
        if isinstance(sv, dict):
            print(f"    keys: {list(sv.keys())}")
            print(f"    val: {json.dumps(sv, ensure_ascii=False)[:300]}")
        elif isinstance(sv, list):
            print(f"    len={len(sv)}")
            if sv:
                print(f"    [0]: {json.dumps(sv[0], ensure_ascii=False)[:300]}")
        else:
            print(f"    val: {str(sv)[:200]}")
elif isinstance(first_val, list):
    print(f"  len={len(first_val)}")
    if first_val:
        print(f"  [0]: {json.dumps(first_val[0], ensure_ascii=False)[:400]}")

# Annotations structure
annotations = data.get("annotations", {})
print(f"\nAnnotations: {len(annotations)} instances")
if annotations:
    ak = list(annotations.keys())[0]
    av = annotations[ak]
    print(f"Sample [{ak}]: type={type(av).__name__}")
    if isinstance(av, dict):
        print(f"  keys: {list(av.keys())[:5]}")
    elif isinstance(av, list):
        print(f"  len={len(av)}")
        if av:
            print(f"  [0]: {json.dumps(av[0], ensure_ascii=False)[:300]}")

# Count all decisions across the full structure
decisions = Counter()
total_segs = 0
for inst_id, inst_data in results.items():
    if isinstance(inst_data, dict):
        # Check if segments are nested
        segments = inst_data.get("segments", inst_data.get("scores", []))
        if isinstance(segments, list):
            for seg in segments:
                total_segs += 1
                if isinstance(seg, dict):
                    d = seg.get("decision", seg.get("label", "MISSING"))
                    decisions[d] += 1
        else:
            # Maybe the dict values themselves are segments
            for sk, sv in inst_data.items():
                if isinstance(sv, dict) and ("decision" in sv or "label" in sv or "score" in sv):
                    total_segs += 1
                    d = sv.get("decision", sv.get("label", "MISSING"))
                    decisions[d] += 1
    elif isinstance(inst_data, list):
        for seg in inst_data:
            total_segs += 1
            if isinstance(seg, dict):
                d = seg.get("decision", seg.get("label", "MISSING"))
                decisions[d] += 1

print(f"\nDecision scan: total_segs={total_segs}, distribution={dict(decisions)}")
PYEOF
